<?php
require 'header.php';
$statuses=['Pending','Confirmed','Processing','Shipped','Out for Delivery','Delivered','Ready for Delivery','Completed','Cancelled','Failed Delivery'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$action=$_POST['action']??'';
 if($id&&$action==='status'&&in_array($_POST['status']??'', $statuses,true)){$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare('SELECT status,stock_restored,order_number,payment_method FROM orders WHERE id=? FOR UPDATE');$s->execute([$id]);$old=$s->fetch();$new=$_POST['status'];if($old&&$new==='Cancelled'&&($old['status']!=='Pending'||$old['payment_method']!=='Cash on Delivery')){$pdo->rollBack();flash('error','Only Pending Cash on Delivery orders can be cancelled here. M-Pesa orders require an off-site payment/refund check first.');header('Location: manage-orders.php');exit;}if($old&&$old['status']!==$new){if((int)$old['stock_restored']&&$new!=='Cancelled'){$pdo->rollBack();flash('error','This cancelled order has had inventory restored and cannot be reopened. Create a new order if needed.');}else{if($new==='Cancelled'&&$old['status']!=='Cancelled'&&!(int)$old['stock_restored']){$lines=$pdo->prepare('SELECT product_id,quantity FROM order_items WHERE order_id=? AND product_id IS NOT NULL');$lines->execute([$id]);$restore=$pdo->prepare('UPDATE products SET stock=stock+? WHERE id=?');$threshold=max(1,(int)setting('low_stock_threshold','3'));$clear=$pdo->prepare('DELETE FROM stock_alerts WHERE product_id=? AND (SELECT stock FROM products WHERE id=?)>=?');foreach($lines as $line){$restore->execute([$line['quantity'],$line['product_id']]);$clear->execute([$line['product_id'],$line['product_id'],$threshold]);}$pdo->prepare('UPDATE orders SET stock_restored=1 WHERE id=?')->execute([$id]);}$pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$new,$id]);$pdo->prepare('INSERT INTO order_status_history(order_id,old_status,new_status,changed_by_admin) VALUES(?,?,?,?)')->execute([$id,$old['status'],$new,$_SESSION['admin_id']]);$pdo->prepare('INSERT INTO admin_audit_log(admin_id,action,entity_type,entity_id,detail) VALUES(?,?,?,?,?)')->execute([$_SESSION['admin_id'],'order_status','order',$old['order_number'],$old['status'].' -> '.$new]);$pdo->commit();flash('success','Order status saved.');}}else{$pdo->commit();flash('success','Order status saved.');}}
 if($id&&$action==='delete'&&($_POST['confirm']??'')==='yes'){$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare('SELECT status,order_number,stock_restored,total,customer_id,payment_method,created_at FROM orders WHERE id=? FOR UPDATE');$s->execute([$id]);$order=$s->fetch();$paid=$pdo->prepare('SELECT COUNT(*) FROM payment_transactions WHERE order_id=?');$paid->execute([$id]);if($order&&$order['status']==='Pending'&&$order['payment_method']==='Cash on Delivery'&&!(int)$order['stock_restored']&&(int)$paid->fetchColumn()===0){$lines=$pdo->prepare('SELECT product_id,product_name,unit_price,quantity FROM order_items WHERE order_id=?');$lines->execute([$id]);$snapshot=['order'=>$order,'items'=>$lines->fetchAll()];$lines->execute([$id]);foreach($lines as $line)if($line['product_id'])$pdo->prepare('UPDATE products SET stock=stock+? WHERE id=?')->execute([$line['quantity'],$line['product_id']]);$pdo->prepare('INSERT INTO admin_audit_log(admin_id,action,entity_type,entity_id,detail) VALUES(?,?,?,?,?)')->execute([$_SESSION['admin_id'],'order_delete','order',$order['order_number'],json_encode($snapshot,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);$pdo->prepare('DELETE FROM orders WHERE id=?')->execute([$id]);$pdo->commit();flash('success','Pending order deleted and inventory restored. A full order snapshot was kept in the audit log.');}else{$pdo->rollBack();flash('error','Only unpaid Cash on Delivery Pending orders can be deleted. Other orders require a payment/refund check first.');}}
 header('Location: manage-orders.php');exit;
}
$q=trim($_GET['q']??'');$status=$_GET['status']??'';$from=$_GET['from']??'';$to=$_GET['to']??'';$where=[];$params=[];
if($q!==''){$where[]='(o.order_number LIKE ? OR c.full_name LIKE ? OR c.phone LIKE ?)';array_push($params,"%$q%","%$q%","%$q%");}
if(in_array($status,$statuses,true)){$where[]='o.status=?';$params[]=$status;}
if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$where[]='o.created_at>=?';$params[]=$from.' 00:00:00';}
if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$where[]='o.created_at<=?';$params[]=$to.' 23:59:59';}
$sql='SELECT o.*,c.full_name,c.phone,c.email,c.address,(SELECT GROUP_CONCAT(CONCAT(oi.product_name," × ",oi.quantity) SEPARATOR ", ") FROM order_items oi WHERE oi.order_id=o.id) items FROM orders o JOIN customers c ON c.id=o.customer_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY o.created_at DESC';$s=db()->prepare($sql);$s->execute($params);$orders=$s->fetchAll();
?>
<div class="admin-title"><p>SALES</p><h2>Manage orders</h2></div>
<form class="inline-form order-filters" method="get"><input name="q" value="<?=e($q)?>" placeholder="Order reference, customer, phone"><select name="status"><option value="">All statuses</option><?php foreach($statuses as $st):?><option value="<?=e($st)?>" <?=$status===$st?'selected':''?>><?=e($st)?></option><?php endforeach?></select><label>From <input type="date" name="from" value="<?=e($from)?>"></label><label>To <input type="date" name="to" value="<?=e($to)?>"></label><button class="save">Filter</button><a href="manage-orders.php">Clear</a></form>
<section class="admin-panel"><table><thead><tr><th>Order &amp; items</th><th>Customer / delivery</th><th>Total / payment</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><strong><?=e($o['order_number'])?></strong><br><small><?=e($o['created_at'])?></small><br><?=e($o['items']??'No line items')?></td><td><?=e($o['full_name'])?><br><?=e($o['phone'])?><br><?=e($o['email'])?><br><?=e($o['address'])?></td><td><?=money($o['total'])?><br><?=e($o['payment_method'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$o['id']?>"><input type="hidden" name="action" value="status"><select name="status"><?php foreach($statuses as $st):?><option <?=$o['status']===$st?'selected':''?>><?=e($st)?></option><?php endforeach?></select><button>Save</button></form></td><td><a href="order-details.php?id=<?=$o['id']?>" aria-label="View order details">View</a><?php if($o['status']==='Pending'):?> · <form class="inline-delete" method="post" onsubmit="return confirm('Delete this pending order? An audit record will be kept.');"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$o['id']?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="confirm" value="yes"><button class="danger">Delete</button></form><?php endif?></td></tr><?php endforeach?></tbody></table><?php if(!$orders):?><p>No orders match these filters.</p><?php endif?></section>
<?php require 'footer.php';
